import{_ as n,C as r,o,c as a,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Resume Recency Is Not Resume Authority","description":"","frontmatter":{"title":"Resume Recency Is Not Resume Authority","date":"2026-08-23","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"When a digital employee resumes after a human interruption, how should reconstructed operator evidence be ordered relative to regenerated or synthetic context?","summary":"A merged Google ADK change shows why resumed agents need occurrence-scoped evidence precedence before model interpretation. Preserving the operator response prevents one shadowing failure, but it does not authenticate the operator or guarantee exactly-once effects.","sources":["research/analysis/Q-20260823-01-resume-evidence-authority.md"],"item_id":"Q-20260823-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-23-resume-recency-not-authority-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-23-resume-recency-not-authority.md","filePath":"en/digital-employee/2026-08-23-resume-recency-not-authority.md","lastUpdated":1787666502000}'),c={name:"en/digital-employee/2026-08-23-resume-recency-not-authority.md"};function d(u,e,h,p,l,m){const t=r("ArticleCover");return o(),a("div",null,[i(t,{image:"/assets/covers/daily-2026-08-23-resume-recency-not-authority-cover-v2.png",kicker:"Digital Employee · Daily Research",title:"Resume Recency Is Not Resume Authority",summary:"A merged Google ADK change shows why resumed agents need occurrence-scoped evidence precedence before model interpretation. Preserving the operator response prevents one shadowing failure, but it does not authenticate the operator or guarantee exactly-once effects.",version:"Q-20260823-01",status:"Daily Runtime V5 · 2026-08-23",languageHref:"/zh/digital-employee/2026-08-23-resume-recency-not-authority",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="resume-recency-is-not-resume-authority" tabindex="-1">Resume Recency Is Not Resume Authority <a class="header-anchor" href="#resume-recency-is-not-resume-authority" aria-label="Permalink to &quot;Resume Recency Is Not Resume Authority&quot;">​</a></h1><p>A human resolves an interruption. The workflow resumes. Then the runtime appends a synthetic copy of the original input after the real response. To a model reading an ordered conversation, the newest user-role event can look like the operative instruction—even though it is the least authoritative event in the sequence.</p><p>That was the failure boundary addressed by a Google ADK change merged on 2026-08-23. ADK reconstructs user <code>FunctionResponse</code> events tied to known interruption identifiers and carries them into child context as <code>resume_inputs</code>. For workflow-wrapped single-turn agents, the input-preparation path now returns early when those inputs are present, instead of appending another synthetic user event.</p><p>The narrow mechanism supports a broader engineering proposition: <strong>resume should preserve a monotonic, occurrence-scoped evidence order before model interpretation.</strong> Once an operator response has been admitted for a specific interruption, regenerated context must not silently outrank it because it was written later. This is evidence continuity—not proof of operator identity, approval freshness or exactly-once execution.</p><h2 id="a-later-event-can-be-less-authoritative" tabindex="-1">A later event can be less authoritative <a class="header-anchor" href="#a-later-event-can-be-less-authoritative" aria-label="Permalink to &quot;A later event can be less authoritative&quot;">​</a></h2><p>The defect was not merely duplicate text. Duplication became dangerous because the events carried different meanings. The persisted <code>FunctionResponse</code> was the response to an identified interruption. The later synthetic event was a wrapper-generated copy of earlier node input. Treating both as interchangeable user prose let append order substitute for an authority rule.</p><p>ADK&#39;s resume path already had richer structure. It scans persisted session events, recognizes responses associated with known interrupt IDs, optionally validates their response schema and reconstructs them as resolved inputs. Explicitly supplied resume inputs can also participate. The resulting mapping therefore represents a continuation lineage that a generic regenerated message does not share.</p><p>The maintainer described repeated human confirmation as the visible failure: synthetic input could shadow the real response and send the agent back through confirmation. The merged regression verifies the decisive condition with a representative non-empty <code>resume_inputs</code> mapping. It does not run a complete persisted tool-confirmation loop, so the evidence supports the input-admission mechanism rather than every end-to-end HITL guarantee.</p><h2 id="enforce-precedence-before-model-interpretation" tabindex="-1">Enforce precedence before model interpretation <a class="header-anchor" href="#enforce-precedence-before-model-interpretation" aria-label="Permalink to &quot;Enforce precedence before model interpretation&quot;">​</a></h2><p>Once conflicting events have entered model context, a system has already delegated precedence to probabilistic interpretation. It may add explanatory prose, sort messages or ask the model to infer that one response is authoritative, but each option leaves the conflict present.</p><p>Suppressing the lower-authority reconstruction earlier is cleaner. The runtime can use interruption identity and resume state—facts it knows deterministically—to decide which events are eligible for context assembly. This turns precedence from a conversational convention into an admission invariant.</p><p>The rule should remain occurrence-scoped. “Older evidence always wins” would be wrong: an operator may intentionally issue a new instruction that supersedes an earlier response. A robust interface should represent that supersession explicitly and bind it to the affected interruption. Otherwise a legitimate override and an accidental synthetic append are indistinguishable in the audit trail.</p><p>For resumable digital employees, this suggests typed resume inputs that carry an occurrence identifier, evidence class and relation to any superseded response. Regression tests should examine ordering and lineage, not only whether the response value survived serialization.</p><h2 id="evidence-continuity-is-not-authorization" tabindex="-1">Evidence continuity is not authorization <a class="header-anchor" href="#evidence-continuity-is-not-authorization" aria-label="Permalink to &quot;Evidence continuity is not authorization&quot;">​</a></h2><p>Preserving the response&#39;s position answers one question: which evidence should the resumed model consume for this interruption? It does not answer several others.</p><p>The system still needs an authenticated principal if the identity of the approver matters. It needs freshness and revocation rules if approval can expire. It needs scope if the response authorizes only one tool call or resource. And it needs effect-level idempotency or reconciliation if a retry could repeat an external action.</p><p>Keeping these controls separate prevents a common guarantee inflation. A workflow that no longer repeats its confirmation prompt has fixed an important continuity bug. It has not thereby established exactly-once approval or exactly-once effects. The public evidence is one merged implementation and its tests, not an independent cross-framework evaluation.</p><p>Low-risk systems may reasonably choose a lighter fresh-turn design. The relevant question is proportionality: if an action is sensitive enough to require human interruption, the runtime should be able to show which occurrence was answered, which evidence was admitted, who was authorized to answer, and what effect consumed that authorization.</p><h2 id="the-guard-is-narrow-and-the-boundary-matters" tabindex="-1">The guard is narrow, and the boundary matters <a class="header-anchor" href="#the-guard-is-narrow-and-the-boundary-matters" aria-label="Permalink to &quot;The guard is narrow, and the boundary matters&quot;">​</a></h2><p>The new condition checks whether any resume input exists. Its simplicity prevents the demonstrated synthetic append, but several interruption channels could share one context. An unrelated resume input might then suppress regeneration for a node whose input should still be produced. The selected evidence does not settle that case.</p><p>The next useful test is therefore not a larger claim. It is a complete persisted HITL loop that records an interruption, accepts a real <code>FunctionResponse</code>, resumes, proves that confirmation terminates, and separately records operator identity and downstream effect handling. Passing that test would extend the evidence surface; it would still need explicit scope before supporting a general guarantee.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/google/adk-python/commit/e753651b7df26febe00bde2cb043225e644cd207" target="_blank" rel="noreferrer">Google ADK merged commit e753651b</a>. The code and regression support the bounded resume-input behavior described here; they are not independent validation of universal HITL safety.</p>',22))])}const f=n(c,[["render",d]]);export{g as __pageData,f as default};
